section.code:
#!/usr/bin/env -S afw --syntax test_script
//? testScript: example.as
//? description: What this file covers
//? sourceType: script
//?
//? test: case-1
//? description: short case title
//? expect: true
//? source: ...

return true;

//?
//? test: case-2
//? description: another case
//? expect: 0
//? source: ...

// body …
return 0;

section.paragraph:
Same-line values, for instance 
//? expect: 0 or 
//? description: short title, have leading 
and trailing whitespace trimmed. You do not need to fuss over 
spaces or tabs after the value.
